//
//  AthleteContext.swift
//  Replog
//
//  A compact, pure digest of the athlete's REAL logged training data, rendered into the
//  on-device planner prompt so the model grounds loads, reps and exercise choices in what
//  the person has actually done — not generic guesses. All math is deterministic and
//  unit-tested; the model only ever sees the rendered summary text.
//
//  The on-device model's context window is small (~4k tokens), so the digest is budgeted:
//  `promptSection(maxTokens:)` drops the least-relevant lifts until the section fits.
//

import Foundation

/// Rough token accounting for prompts sent to the on-device model.
/// FoundationModels exposes no public token counter, so we estimate conservatively at
/// ~3.5 characters per token for English prose (real prose averages nearer 4).
enum PromptBudget {
    /// The on-device model's approximate context window (input + output), in tokens.
    static let contextWindow = 4096
    /// Tokens reserved for the model's structured response.
    static let responseReserve = 1400

    /// Conservative token estimate for a piece of prompt text.
    static func estimatedTokens(_ text: String) -> Int {
        Int((Double(text.count) / 3.5).rounded(.up))
    }

    /// Tokens left for additional prompt content once the fixed parts and the
    /// response reserve are accounted for. Never negative.
    static func remainingTokens(afterFixed parts: String...) -> Int {
        let used = parts.reduce(0) { $0 + estimatedTokens($1) }
        return max(0, contextWindow - responseReserve - used)
    }
}

/// One lift's recent history, distilled to what a coach needs to program it.
struct LiftDigest: Equatable, Sendable {
    var exId: String
    var name: String
    var lastTopWeightKg: Double
    var lastTopReps: Int
    var currentE1rm: Int
    var bestE1rm: Int
    /// e1RM change of the latest session vs the prior one, or nil with fewer than 2 sessions.
    var trendPercent: Double?
    var sessionCount: Int

    /// Full line for the framing prompt's history section.
    var promptLine: String {
        "\(name): last top set \(Self.kgText(lastTopWeightKg)) kg × \(lastTopReps), " +
        "est 1RM \(currentE1rm) kg (best \(bestE1rm) kg), \(trendText), " +
        "\(sessionCount) session\(sessionCount == 1 ? "" : "s") logged"
    }

    /// Short annotation appended to a matching candidate in the selection prompt.
    var shortNote: String {
        "logged: last \(Self.kgText(lastTopWeightKg)) kg × \(lastTopReps), \(trendText)"
    }

    private var trendText: String {
        guard let trendPercent else { return "no trend yet" }
        if trendPercent > 0 { return String(format: "up %.1f%% vs previous", trendPercent) }
        if trendPercent < 0 { return String(format: "down %.1f%% vs previous", -trendPercent) }
        return "flat vs previous"
    }

    private static func kgText(_ kg: Double) -> String {
        kg == kg.rounded() ? String(Int(kg)) : String(format: "%.1f", kg)
    }
}

/// Working sets logged for one muscle over the trailing week.
struct MuscleSetVolume: Equatable, Sendable {
    var muscle: Muscle
    var sets: Int
}

/// The athlete's recent training, summarised for the planner. Pure value type:
/// build it with `make(history:catalog:now:)`, render it with `promptSection(maxTokens:)`.
struct AthleteContext: Equatable, Sendable {
    /// Per-lift digests, most relevant first (most-trained, then most recent).
    var lifts: [LiftDigest] = []
    /// Working sets per primary muscle over the trailing 7 days, highest volume first.
    var weeklySetsPerMuscle: [MuscleSetVolume] = []

    var isEmpty: Bool { lifts.isEmpty }

    // Nonisolated so it can serve as a default argument from any isolation context.
    nonisolated static let empty = AthleteContext()

    /// The digest for a specific catalog exercise, if the athlete has logged it recently.
    func digest(forExId exId: String) -> LiftDigest? {
        lifts.first { $0.exId == exId }
    }

    // MARK: - Building

    /// Summarises history entries within the trailing `windowDays` (stale lifts are not
    /// coaching-relevant), keeping the `maxLifts` most relevant lifts. Entries whose
    /// exercise no longer resolves in the catalog are skipped.
    static func make(history: [HistoryEntry],
                     catalog: ExerciseCatalog,
                     now: Date = Date(),
                     windowDays: Int = 56,
                     maxLifts: Int = 10) -> AthleteContext {
        let calendar = Calendar.current
        let cutoff = calendar.date(byAdding: .day, value: -windowDays, to: now) ?? now
        let recent = history.filter { $0.date >= cutoff }
        guard !recent.isEmpty else { return .empty }

        // Per-lift digests, reusing the tested progress math.
        var ranked: [(digest: LiftDigest, lastDate: Date)] = []
        for (exId, entries) in Dictionary(grouping: recent, by: \.exId) {
            guard let exercise = catalog.exercise(id: exId),
                  let latest = entries.max(by: { $0.date < $1.date }) else { continue }
            let progress = ProgressAggregator.summarize(exId: exId, history: entries)
            ranked.append((LiftDigest(exId: exId,
                                      name: exercise.name,
                                      lastTopWeightKg: latest.topW,
                                      lastTopReps: latest.topR,
                                      currentE1rm: progress.currentE1rm,
                                      bestE1rm: progress.bestE1rm,
                                      trendPercent: progress.trendPercent,
                                      sessionCount: progress.sessionCount),
                           latest.date))
        }
        ranked.sort {
            if $0.digest.sessionCount != $1.digest.sessionCount {
                return $0.digest.sessionCount > $1.digest.sessionCount
            }
            if $0.lastDate != $1.lastDate { return $0.lastDate > $1.lastDate }
            return $0.digest.name < $1.digest.name
        }

        // Weekly volume per primary muscle (trailing 7 days).
        let weekCutoff = calendar.date(byAdding: .day, value: -7, to: now) ?? now
        var setsByMuscle: [Muscle: Int] = [:]
        for entry in recent where entry.date >= weekCutoff {
            guard let exercise = catalog.exercise(id: entry.exId) else { continue }
            let sets = max(entry.sets.count, 1)  // the top set exists even if setsJSON is empty
            for muscle in exercise.primaryMuscles {
                setsByMuscle[muscle, default: 0] += sets
            }
        }
        let weekly = setsByMuscle
            .map { MuscleSetVolume(muscle: $0.key, sets: $0.value) }
            .sorted {
                $0.sets != $1.sets ? $0.sets > $1.sets : $0.muscle.rawValue < $1.muscle.rawValue
            }

        return AthleteContext(lifts: Array(ranked.prefix(maxLifts)).map(\.digest),
                              weeklySetsPerMuscle: weekly)
    }

    // MARK: - Rendering

    /// The history section for the framing prompt, or "" when there's no history or no
    /// budget. Drops the least-relevant lifts until the section fits `maxTokens`.
    func promptSection(maxTokens: Int) -> String {
        guard !isEmpty, maxTokens > 0 else { return "" }
        let header = """
        RECENT LOGGED TRAINING (real data — ground your loads, reps and exercise choices in it; \
        progress lifts trending up, hold or vary lifts that stall or regress):
        """
        let volumeLine: String = weeklySetsPerMuscle.isEmpty ? "" :
            "Working sets in the last 7 days: " +
            weeklySetsPerMuscle.map { "\($0.muscle.displayName) \($0.sets)" }.joined(separator: ", ") + "."

        var included = lifts
        while !included.isEmpty {
            let body = included.map { "• " + $0.promptLine }.joined(separator: "\n")
            let section = [header, body, volumeLine].filter { !$0.isEmpty }.joined(separator: "\n")
            if PromptBudget.estimatedTokens(section) <= maxTokens { return section }
            included.removeLast()
        }
        return ""
    }
}

//
//  AIPlanService.swift
//  Replog
//
//  The Apple Intelligence boundary. Generation is genuinely model-driven and two-stage:
//
//   1. Framing call — the model designs the split (per-day muscle focus, volume, rep/RPE
//      scheme) and writes the report's overall sections.
//   2. Per-day selection calls — for each day the model is given a numbered list of REAL
//      catalog exercises (filtered to the user's equipment/injuries) and picks specific ones,
//      justifying each. Picks are validated against the catalog so refs/images stay valid.
//
//  A non-zero sampling temperature means the same answers can yield different, equally-valid
//  plans across sessions — as the user expects from an AI. If the model is unavailable or
//  errors, it falls back to the deterministic engine (clearly flagged via `usedAppleIntelligence`).
//

import Foundation
import FoundationModels

@MainActor
struct AIPlanService {

    /// A generated plan plus its saved report and which engine produced it.
    struct Result: Equatable, Sendable {
        var plan: GeneratedPlan
        var reportMarkdown: String
        var usedAppleIntelligence: Bool
    }

    let generator: PlanGenerator
    let resolver: PlanResolver
    /// Forces the deterministic path (used by tests so they never invoke the live model).
    let forceFallback: Bool
    /// Sampling temperature — higher means more run-to-run variety.
    let temperature: Double

    nonisolated init(catalog: ExerciseCatalog = .shared, forceFallback: Bool = false, temperature: Double = 1.0) {
        self.generator = PlanGenerator(catalog: catalog)
        self.resolver = PlanResolver()
        self.forceFallback = forceFallback
        self.temperature = temperature
    }

    /// Whether Apple Intelligence can generate on this device right now.
    static var isAvailable: Bool {
        if case .available = SystemLanguageModel.default.availability { return true }
        return false
    }

    /// Generates a plan + report. Uses Apple Intelligence when available, else falls back.
    /// `athlete` carries the user's real logged training (empty on first onboarding) so the
    /// model can ground loads, reps and exercise choices in actual history.
    func generate(_ answers: QuizAnswers, athlete: AthleteContext = .empty) async -> Result {
        guard !forceFallback, Self.isAvailable else {
            return Self.fallback(answers: answers, generator: generator)
        }
        do {
            return try await generateWithAI(answers, athlete: athlete)
        } catch {
            return Self.fallback(answers: answers, generator: generator)
        }
    }

    // MARK: - Live two-stage generation

    private func generateWithAI(_ answers: QuizAnswers, athlete: AthleteContext) async throws -> Result {
        let options = GenerationOptions(temperature: temperature)

        // 1) Framing: the model designs the split + report sections.
        let framingSession = LanguageModelSession(instructions: Self.framingInstructions)
        let framing = try await framingSession.respond(
            to: Self.framingPrompt(for: answers, athlete: athlete),
            generating: PlanFraming.self,
            options: options
        ).content

        guard !framing.workouts.isEmpty else {
            return Self.fallback(answers: answers, generator: generator)
        }

        // 2) Per-day: the model selects + justifies specific real exercises.
        let weekdays = PlanGenerator.weekdays(count: framing.workouts.count)
        var workouts: [GeneratedWorkout] = []
        var reportDays: [PerDayNote] = []

        for (index, day) in framing.workouts.enumerated() {
            let muscles = day.targetMuscles.compactMap { Muscle.lenient($0) }
            let candidates = generator.candidates(forMuscles: muscles, answers: answers, limit: 14)
            guard !candidates.isEmpty else { continue }

            let count = max(3, min(6, day.exerciseCount))
            let selectionSession = LanguageModelSession(instructions: Self.selectionInstructions)
            let selection = try await selectionSession.respond(
                to: Self.selectionPrompt(day: day, candidates: candidates, count: count,
                                         answers: answers, athlete: athlete),
                generating: DaySelection.self,
                options: options
            ).content

            let resolved = resolver.resolveDay(day: day, selection: selection, candidates: candidates)
            guard !resolved.items.isEmpty else { continue }

            let weekday = index < weekdays.count ? weekdays[index] : Weekday.allCases[index % 7]
            let name = day.name.trimmingCharacters(in: .whitespaces).isEmpty ? "Day \(index + 1)" : day.name
            workouts.append(GeneratedWorkout(name: name, day: weekday, items: resolved.items))
            reportDays.append(PerDayNote(
                dayName: name,
                text: selection.dayRationale.trimmingCharacters(in: .whitespacesAndNewlines),
                exercises: resolved.notes
            ))
        }

        guard !workouts.isEmpty else {
            return Self.fallback(answers: answers, generator: generator)
        }

        let planName = framing.planName.trimmingCharacters(in: .whitespaces)
        let headline = framing.headline.trimmingCharacters(in: .whitespaces)
        let plan = GeneratedPlan(
            name: planName.isEmpty ? "Your Plan" : planName,
            colorHex: PlanGenerator.planColor(for: answers.goal),
            workouts: workouts,
            headline: headline.isEmpty ? "Your Plan" : headline
        )
        let report = PlanReport(
            philosophy: framing.philosophy,
            whyThisSplit: framing.whyThisSplit,
            perDay: reportDays,
            scienceNotes: framing.scienceNotes,
            safetyNotes: framing.safetyNotes,
            encouragement: framing.encouragement
        )
        return Result(plan: plan, reportMarkdown: ReportComposer.markdown(report: report, plan: plan),
                      usedAppleIntelligence: true)
    }

    // MARK: - Deterministic fallback (no model). Directly unit-tested.

    static func fallback(answers: QuizAnswers, generator: PlanGenerator = PlanGenerator()) -> Result {
        let plan = generator.generate(answers)
        let report = ReportComposer.fallbackMarkdown(answers: answers, plan: plan)
        return Result(plan: plan, reportMarkdown: report, usedAppleIntelligence: false)
    }

    // MARK: - Prompts

    static let framingInstructions = CoachingKnowledge.grounded("""
    You are an elite, caring strength & conditioning coach and exercise scientist who designs \
    safe, evidence-based resistance-training programs tailored to the individual. Use warm, plain, \
    encouraging language. Design the split and explain your reasoning thoroughly, citing the \
    principles below in plain words.
    """)

    static let selectionInstructions = CoachingKnowledge.grounded("""
    You are an elite exercise scientist selecting specific exercises for one training day from a \
    provided list of real, available exercises. Choose the best mix of compound and isolation \
    movements for the day's muscles and the person's level and equipment. For EACH exercise, \
    explain in plain language what it trains and why it earns its place in this session. Only \
    choose from the numbered candidates given.
    """)

    static func framingPrompt(for answers: QuizAnswers, athlete: AthleteContext = .empty) -> String {
        let base = """
        Design a personalized resistance-training plan for this person:

        \(profileLines(answers))

        Produce exactly \(answers.daysPerWeek) training day(s). For each day give a name, its 2-4 \
        primary muscle groups (lowercase single words), the number of exercises (3-6), and the rep, \
        RPE, and set scheme. Then write the report sections: philosophy, why this split and why these \
        muscles are paired together, the science, safety adaptations, and an encouraging note.
        """
        // The athlete's logged history gets whatever token budget the fixed parts leave over.
        let history = athlete.promptSection(
            maxTokens: PromptBudget.remainingTokens(afterFixed: framingInstructions, base))
        return history.isEmpty ? base : base + "\n\n" + history
    }

    static func selectionPrompt(day: DayFraming, candidates: [Exercise], count: Int,
                                answers: QuizAnswers, athlete: AthleteContext = .empty) -> String {
        let list = candidates.enumerated().map { i, ex in
            let muscle = ex.primaryMuscles.first?.displayName ?? "—"
            let equip = ex.equipment?.displayName ?? "Bodyweight"
            let mech = ex.mechanic?.displayName ?? ""
            let base = "\(i + 1). \(ex.name) — \(muscle), \(equip)\(mech.isEmpty ? "" : ", \(mech)")"
            guard let digest = athlete.digest(forExId: ex.id) else { return base }
            return base + " [\(digest.shortNote)]"
        }.joined(separator: "\n")

        let historyHint = athlete.isEmpty ? "" : """
         Candidates marked [logged: …] are lifts the person already trains — prefer keeping ones \
        that are progressing, and consider a variation where one stalls.
        """

        return """
        Training day: "\(day.name)" focusing on \(day.targetMuscles.joined(separator: ", ")).
        Person: \(answers.goal.displayName), \(answers.experience.displayName), equipment: \
        \(answers.equipmentDescription)\(answers.injuries.isEmpty ? "" : ", limitations: \(answers.injuries.map(\.displayName).joined(separator: ", "))").

        Choose exactly \(count) exercises for this day from the candidates below, in the order they \
        should be performed (compound movements first). Give the candidate number and a clear reason \
        for each.\(historyHint)

        Candidates:
        \(list)
        """
    }

    private static func profileLines(_ answers: QuizAnswers) -> String {
        var lines: [String] = []
        if !answers.fullName.isEmpty { lines.append("Name: \(answers.fullName)") }
        lines.append("Goal: \(answers.goal.displayName)")
        if answers.goal == .sport, !answers.sportLabel.isEmpty { lines.append("Sport: \(answers.sportLabel)") }
        lines.append("Experience: \(answers.experience.displayName)")
        lines.append("Gender: \(answers.gender.displayName)")
        lines.append("Age: \(answers.age)")
        lines.append("Height: \(answers.heightCm) cm")
        lines.append("Body weight: \(Int(answers.bodyWeightKg)) kg")
        if let bmi = answers.bmi {
            lines.append(String(format: "BMI: %.1f (%@)", bmi, answers.bmiCategory ?? ""))
        }
        lines.append("Training days per week: \(answers.daysPerWeek)")
        lines.append("Time per session: ~\(answers.minutesPerSession) min")
        lines.append("Equipment available (use ONLY these): \(answers.equipmentDescription)")
        lines.append("Injuries / limitations: \(answers.injuries.isEmpty ? "none" : answers.injuries.map(\.displayName).joined(separator: ", "))")
        return lines.joined(separator: "\n")
    }
}

//
//  PlanGenerator.swift
//  Replog
//
//  The on-device "AI": a deterministic engine that builds a training Plan from the
//  onboarding answers using the real exercise catalog. Same input -> same plan.
//  (The UI shows a ~1.8s "Building your plan" spinner over this work.)
//

import Foundation

// MARK: - Output (pure value types, no SwiftData)

struct GeneratedSet: Equatable, Sendable {
    var weightKg: Double
    var reps: Int
    var rpe: Int
}

struct GeneratedItem: Equatable, Sendable {
    var exId: String
    var sets: [GeneratedSet]
}

struct GeneratedWorkout: Equatable, Sendable {
    var name: String
    var day: Weekday
    var items: [GeneratedItem]
}

struct GeneratedPlan: Equatable, Sendable {
    var name: String
    var colorHex: String
    var workouts: [GeneratedWorkout]
    /// Display header on the result screen, e.g. "Your Hypertrophy Plan".
    var headline: String
}

// MARK: - Generator

struct PlanGenerator {
    let catalog: ExerciseCatalog

    nonisolated init(catalog: ExerciseCatalog = .shared) {
        self.catalog = catalog
    }

    /// Builds a complete plan for the given answers. Deterministic.
    func generate(_ answers: QuizAnswers) -> GeneratedPlan {
        let split = Split.choose(forDays: answers.daysPerWeek)
        let days = Self.weekdays(count: split.dayTemplates.count)
        let perWorkout = exercisesPerWorkout(minutes: answers.minutesPerSession)
        let allowed = answers.allowedEquipment
        let avoid = answers.avoidedMuscles
        let priority = priorityMuscles(answers)

        var workouts: [GeneratedWorkout] = []
        for (index, template) in split.dayTemplates.enumerated() {
            let items = buildItems(
                for: template,
                priority: priority,
                count: perWorkout,
                allowedEquipment: allowed,
                avoidMuscles: avoid,
                answers: answers
            )
            workouts.append(GeneratedWorkout(name: template.name, day: days[index], items: items))
        }

        return GeneratedPlan(
            name: split.planName,
            colorHex: Self.planColor(for: answers.goal),
            workouts: workouts,
            headline: headline(for: answers.goal)
        )
    }

    // MARK: Exercise selection

    /// Selects real catalog exercises for an arbitrary set of target muscles, honoring the
    /// user's equipment/injury constraints. Used by the AI resolver to map a blueprint's
    /// per-day muscle targets onto valid catalog exercises (guaranteeing images/refs exist).
    func selectItems(targetMuscles: [Muscle], count: Int, answers: QuizAnswers) -> [GeneratedItem] {
        let muscles = targetMuscles.isEmpty ? priorityMuscles(answers) : targetMuscles
        let template = DayTemplate(name: "", muscles: muscles)
        return buildItems(
            for: template,
            priority: priorityMuscles(answers),
            count: max(1, count),
            allowedEquipment: answers.allowedEquipment,
            avoidMuscles: answers.avoidedMuscles,
            answers: answers
        )
    }

    /// Real catalog exercises the AI can choose from for a day's target muscles, honoring the
    /// user's equipment/injury constraints. Interleaves across muscles for balance and ranks
    /// compound-first; capped at `limit`. The model picks from (and justifies) this list.
    func candidates(forMuscles muscles: [Muscle], answers: QuizAnswers, limit: Int = 14) -> [Exercise] {
        let allowed = answers.allowedEquipment
        let avoid = answers.avoidedMuscles
        let target = muscles.isEmpty ? priorityMuscles(answers) : muscles

        var perMuscle: [[Exercise]] = target.map { muscle in
            catalog.exercises(forMuscle: muscle)
                .filter { ex in
                    guard ex.primaryMuscles.contains(muscle) else { return false }
                    // Missing equipment counts as bodyweight, so a machine-only user never
                    // gets a bodyweight exercise slipped in.
                    if !allowed.contains(ex.equipment ?? .bodyOnly) { return false }
                    if !avoid.isEmpty, ex.primaryMuscles.contains(where: avoid.contains) { return false }
                    return true
                }
                .sorted { a, b in
                    let ra = rank(a, preferCompound: true), rb = rank(b, preferCompound: true)
                    if ra != rb { return ra < rb }
                    return a.name.localizedCaseInsensitiveCompare(b.name) == .orderedAscending
                }
        }

        var seen = Set<String>()
        var result: [Exercise] = []
        var i = 0
        while result.count < limit, perMuscle.contains(where: { !$0.isEmpty }) {
            let m = i % perMuscle.count
            if !perMuscle[m].isEmpty {
                let ex = perMuscle[m].removeFirst()
                if seen.insert(ex.id).inserted { result.append(ex) }
            }
            i += 1
        }
        return result
    }

    private func buildItems(
        for template: DayTemplate,
        priority: [Muscle],
        count: Int,
        allowedEquipment: Set<Equipment>,
        avoidMuscles: Set<Muscle>,
        answers: QuizAnswers
    ) -> [GeneratedItem] {
        // Order this day's target muscles by the user's global priority, then template order.
        let orderedTargets = template.muscles.sorted { lhs, rhs in
            let li = priority.firstIndex(of: lhs) ?? Int.max
            let ri = priority.firstIndex(of: rhs) ?? Int.max
            if li != ri { return li < ri }
            let ti = template.muscles.firstIndex(of: lhs) ?? 0
            let tj = template.muscles.firstIndex(of: rhs) ?? 0
            return ti < tj
        }

        var chosen: [Exercise] = []
        var usedIDs = Set<String>()

        // One pass picking the best exercise per target muscle, looping until we hit `count`.
        var pass = 0
        while chosen.count < count, pass < 4 {
            for muscle in orderedTargets where chosen.count < count {
                let candidate = bestExercise(
                    for: muscle,
                    allowedEquipment: allowedEquipment,
                    avoidMuscles: avoidMuscles,
                    excluding: usedIDs,
                    preferCompound: pass == 0
                )
                if let candidate {
                    chosen.append(candidate)
                    usedIDs.insert(candidate.id)
                }
            }
            pass += 1
        }

        return chosen.map { ex in
            GeneratedItem(exId: ex.id, sets: setTemplate(for: ex, answers: answers))
        }
    }

    /// The best catalog exercise for a muscle under the constraints, or nil.
    private func bestExercise(
        for muscle: Muscle,
        allowedEquipment: Set<Equipment>,
        avoidMuscles: Set<Muscle>,
        excluding usedIDs: Set<String>,
        preferCompound: Bool
    ) -> Exercise? {
        let candidates = catalog.exercises(forMuscle: muscle).filter { ex in
            guard !usedIDs.contains(ex.id) else { return false }
            // Equipment must be permitted; missing equipment counts as bodyweight.
            if !allowedEquipment.contains(ex.equipment ?? .bodyOnly) { return false }
            // Don't load an avoided region as a primary mover.
            if !avoidMuscles.isEmpty, ex.primaryMuscles.contains(where: avoidMuscles.contains) { return false }
            // Must actually target this muscle as primary for a strong stimulus.
            return ex.primaryMuscles.contains(muscle)
        }
        // Deterministic ranking: compound first (if preferred), then strength category,
        // then stable by name.
        return candidates.min { a, b in
            let aScore = rank(a, preferCompound: preferCompound)
            let bScore = rank(b, preferCompound: preferCompound)
            if aScore != bScore { return aScore < bScore }
            return a.name.localizedCaseInsensitiveCompare(b.name) == .orderedAscending
        }
    }

    private func rank(_ ex: Exercise, preferCompound: Bool) -> Int {
        var score = 0
        if preferCompound { score += ex.mechanic == .compound ? 0 : 2 }
        score += ex.category == .strength ? 0 : 1
        return score
    }

    // MARK: Set/rep prescription

    private func setTemplate(for ex: Exercise, answers: QuizAnswers) -> [GeneratedSet] {
        let setCount: Int = {
            switch answers.experience {
            case .beginner: return 3
            case .intermediate: return ex.mechanic == .compound ? 4 : 3
            case .advanced: return 4
            }
        }()
        let reps: Int = {
            switch answers.goal {
            case .buildMuscle, .recomp: return 10
            case .loseWeight: return 13
            case .sport: return 8
            }
        }()
        let rpe: Int = {
            switch answers.experience {
            case .beginner: return 7
            case .intermediate: return 8
            case .advanced: return 9
            }
        }()
        let weight = Self.startingWeight(for: ex)
        return Array(repeating: GeneratedSet(weightKg: weight, reps: reps, rpe: rpe), count: setCount)
    }

    /// A sensible starting prescription (kg) the user can tune. Bodyweight = 0.
    static func startingWeight(for ex: Exercise) -> Double {
        switch ex.equipment {
        case .none, .bodyOnly, .bands, .foamRoll, .exerciseBall: return 0
        case .barbell, .ezCurlBar: return ex.mechanic == .compound ? 40 : 20
        case .dumbbell, .kettlebells: return ex.mechanic == .compound ? 16 : 8
        case .machine, .cable: return 25
        case .medicineBall, .other: return 6
        }
    }

    // MARK: Priorities & cosmetics

    private func priorityMuscles(_ answers: QuizAnswers) -> [Muscle] {
        // A known sport biases the plan; "Other"/custom sports have no fixed mapping
        // (empty priorities) and fall through to the general list below.
        if answers.goal == .sport, let sport = answers.sport, !sport.priorityMuscles.isEmpty {
            return sport.priorityMuscles
        }
        // General hypertrophy / recomp / fat-loss: big movers first.
        return [.chest, .lats, .quadriceps, .hamstrings, .shoulders, .glutes,
                .middleBack, .biceps, .triceps, .calves, .abdominals]
    }

    private func exercisesPerWorkout(minutes: Int) -> Int {
        min(6, max(3, minutes / 12))
    }

    private func headline(for goal: Goal) -> String {
        switch goal {
        case .buildMuscle: return "Your Hypertrophy Plan"
        case .loseWeight:  return "Your Fat-Loss Plan"
        case .recomp:      return "Your Recomposition Plan"
        case .sport:       return "Your Sport Plan"
        }
    }

    static func planColor(for goal: Goal) -> String {
        switch goal {
        case .buildMuscle: return "#FF6A3D"
        case .loseWeight:  return "#2FA779"
        case .recomp:      return "#3D7DFF"
        case .sport:       return "#B36AFF"
        }
    }

    /// Weekdays spread across the week for `count` training days.
    static func weekdays(count: Int) -> [Weekday] {
        switch count {
        case ...2: return [.mon, .thu]
        case 3:    return [.mon, .wed, .fri]
        case 4:    return [.mon, .tue, .thu, .fri]
        case 5:    return [.mon, .tue, .wed, .fri, .sat]
        case 6:    return [.mon, .tue, .wed, .thu, .fri, .sat]
        default:   return [.mon, .tue, .wed, .thu, .fri, .sat, .sun] // 7 days, no rest day
        }
    }
}

// MARK: - Splits & day templates

struct DayTemplate: Equatable, Sendable {
    var name: String
    var muscles: [Muscle]
}

struct Split: Equatable, Sendable {
    var planName: String
    var dayTemplates: [DayTemplate]

    static let push = DayTemplate(name: "Push Day", muscles: [.chest, .shoulders, .triceps])
    static let pull = DayTemplate(name: "Pull Day", muscles: [.lats, .middleBack, .biceps, .traps])
    static let legs = DayTemplate(name: "Leg Day", muscles: [.quadriceps, .hamstrings, .glutes, .calves])
    static let upper = DayTemplate(name: "Upper Day", muscles: [.chest, .lats, .shoulders, .biceps, .triceps])
    static let lower = DayTemplate(name: "Lower Day", muscles: [.quadriceps, .hamstrings, .glutes, .calves])
    static let full = DayTemplate(name: "Full Body", muscles: [.chest, .lats, .quadriceps, .shoulders, .hamstrings])
    static let arms = DayTemplate(name: "Arms & Core", muscles: [.biceps, .triceps, .forearms, .abdominals])

    /// Picks a split appropriate to the number of training days.
    static func choose(forDays days: Int) -> Split {
        switch days {
        case ...2:
            return Split(planName: "Upper / Lower", dayTemplates: [upper, lower])
        case 3:
            return Split(planName: "Push · Pull · Legs", dayTemplates: [push, pull, legs])
        case 4:
            return Split(planName: "Upper / Lower", dayTemplates: [upper, lower, upper, lower])
        case 5:
            return Split(planName: "Push · Pull · Legs + Upper / Lower",
                         dayTemplates: [push, pull, legs, upper, lower])
        case 6:
            return Split(planName: "Push · Pull · Legs ×2",
                         dayTemplates: [push, pull, legs, push, pull, legs])
        default:
            // 7 days, no rest day: high-frequency week touching every region.
            return Split(planName: "Push · Pull · Legs + Upper / Lower + Arms",
                         dayTemplates: [push, pull, legs, upper, lower, arms, full])
        }
    }
}

//
//  AIPlanServiceTests.swift
//  ReplogTests
//
//  The Apple Intelligence boundary's deterministic surfaces: prompts embed the user's
//  profile and the real candidate list, instructions are science-grounded, and the fallback
//  always yields a valid plan + report.
//

import Testing
import Foundation
@testable import Replog

@MainActor
struct AIPlanServiceTests {

    @Test func framingPromptEmbedsUserProfile() {
        var a = QuizAnswers()
        a.firstName = "Sam"
        a.goal = .sport; a.sport = .running
        a.heightCm = 178; a.bodyWeightKg = 72
        a.daysPerWeek = 4
        a.injuries = [.knee]
        let prompt = AIPlanService.framingPrompt(for: a)

        #expect(prompt.contains("Name: Sam"))
        #expect(prompt.contains("Running"))
        #expect(prompt.contains("178 cm"))
        #expect(prompt.contains("exactly 4"))
        #expect(prompt.contains("Knee"))
    }

    @Test func selectionPromptListsNumberedCandidates() {
        let g = PlanGenerator(catalog: ExerciseCatalog(bundle: .main))
        let candidates = g.candidates(forMuscles: [.chest], answers: QuizAnswers(), limit: 6)
        #expect(candidates.count >= 3)
        let day = DayFraming(name: "Push", targetMuscles: ["chest"], exerciseCount: 4, reps: 10, rpe: 8, sets: 4)
        let prompt = AIPlanService.selectionPrompt(day: day, candidates: candidates, count: 4, answers: QuizAnswers())

        #expect(prompt.contains("1. "))
        #expect(prompt.contains("Choose exactly 4"))
        #expect(prompt.contains(candidates[0].name))
    }

    @Test func instructionsAreGroundedInScience() {
        #expect(AIPlanService.framingInstructions.contains("Volume"))
        #expect(AIPlanService.framingInstructions.contains("Frequency"))
        #expect(AIPlanService.selectionInstructions.contains("compound"))
        #expect(CoachingKnowledge.principles.contains("Progressive overload"))
    }

    @Test func framingPromptEmbedsLoggedHistory() throws {
        let catalog = ExerciseCatalog(bundle: .main)
        let bench = try #require(catalog.exercises(forMuscle: .chest).first)
        let now = Date(timeIntervalSince1970: 1_750_000_000)
        let history = [
            HistoryEntry(exId: bench.id, date: now.addingTimeInterval(-10 * 86_400),
                         topW: 80, topR: 8, e1rm: Formulas.e1rmRounded(kg: 80, reps: 8),
                         sets: [RecordedSet(w: 80, r: 8)]),
            HistoryEntry(exId: bench.id, date: now.addingTimeInterval(-3 * 86_400),
                         topW: 82.5, topR: 8, e1rm: Formulas.e1rmRounded(kg: 82.5, reps: 8),
                         sets: [RecordedSet(w: 82.5, r: 8)]),
        ]
        let athlete = AthleteContext.make(history: history, catalog: catalog, now: now)
        let answers = QuizAnswers()

        let rich = AIPlanService.framingPrompt(for: answers, athlete: athlete)
        let empty = AIPlanService.framingPrompt(for: answers)

        // A persona with history produces a visibly different prompt than an empty one.
        #expect(rich != empty)
        #expect(rich.contains("RECENT LOGGED TRAINING"))
        #expect(rich.contains(bench.name))
        #expect(!empty.contains("RECENT LOGGED TRAINING"))
    }

    @Test func framingPromptStaysUnderTokenBudgetWithMargin() {
        let catalog = ExerciseCatalog(bundle: .main)
        let now = Date(timeIntervalSince1970: 1_750_000_000)
        // A worst-case athlete: many distinct lifts across many muscles, all recent.
        let muscles: [Muscle] = [.chest, .quadriceps, .lats, .shoulders, .hamstrings, .biceps]
        let history = muscles.flatMap { muscle in
            catalog.exercises(forMuscle: muscle).prefix(3).map { ex in
                HistoryEntry(exId: ex.id, date: now.addingTimeInterval(-2 * 86_400),
                             topW: 61.25, topR: 12, e1rm: Formulas.e1rmRounded(kg: 61.25, reps: 12),
                             sets: Array(repeating: RecordedSet(w: 61.25, r: 12), count: 4))
            }
        }
        let athlete = AthleteContext.make(history: history, catalog: catalog, now: now)
        var answers = QuizAnswers()
        answers.injuries = [.knee, .shoulder, .lowerBack]  // longest profile lines

        let prompt = AIPlanService.framingPrompt(for: answers, athlete: athlete)
        let inputTokens = PromptBudget.estimatedTokens(AIPlanService.framingInstructions)
            + PromptBudget.estimatedTokens(prompt)

        // Instructions + prompt must leave the full response reserve inside the window.
        #expect(inputTokens + PromptBudget.responseReserve <= PromptBudget.contextWindow)
    }

    @Test func selectionPromptAnnotatesLoggedCandidates() throws {
        let catalog = ExerciseCatalog(bundle: .main)
        let g = PlanGenerator(catalog: catalog)
        let candidates = g.candidates(forMuscles: [.chest], answers: QuizAnswers(), limit: 6)
        let logged = try #require(candidates.first)
        let now = Date(timeIntervalSince1970: 1_750_000_000)
        let history = [HistoryEntry(exId: logged.id, date: now.addingTimeInterval(-86_400),
                                    topW: 80, topR: 8, e1rm: Formulas.e1rmRounded(kg: 80, reps: 8),
                                    sets: [RecordedSet(w: 80, r: 8)])]
        let athlete = AthleteContext.make(history: history, catalog: catalog, now: now)
        let day = DayFraming(name: "Push", targetMuscles: ["chest"], exerciseCount: 4, reps: 10, rpe: 8, sets: 4)

        let prompt = AIPlanService.selectionPrompt(day: day, candidates: candidates, count: 4,
                                                   answers: QuizAnswers(), athlete: athlete)

        #expect(prompt.contains("[logged: last 80 kg × 8"))
        #expect(prompt.contains("prefer keeping ones"))
    }

    @Test func fallbackAlwaysProducesValidPlanAndReport() async {
        let service = AIPlanService(catalog: ExerciseCatalog(bundle: .main), forceFallback: true)
        var a = QuizAnswers()
        a.daysPerWeek = 6
        let result = await service.generate(a)

        #expect(result.usedAppleIntelligence == false)
        #expect(result.plan.workouts.count == 6)
        #expect(result.plan.workouts.allSatisfy { !$0.items.isEmpty })
        #expect(result.reportMarkdown.contains("# "))
        #expect(result.reportMarkdown.contains("## The science"))
    }
}

