//
//  Enums.swift
//  Replog
//
//  Shared enumerations for the static exercise catalog and user data.
//  All string enums decode leniently so every entry in the Free Exercise DB
//  parses even if a future value is added upstream.
//

import Foundation

/// A muscle group targeted by an exercise (Free Exercise DB taxonomy).
enum Muscle: String, Codable, CaseIterable, Identifiable, Sendable {
    case abdominals, abductors, adductors, biceps, calves, chest, forearms
    case glutes, hamstrings, lats, lowerBack = "lower back", middleBack = "middle back"
    case neck, quadriceps, shoulders, traps, triceps

    var id: String { rawValue }

    /// Human-facing, capitalized label ("lower back" -> "Lower Back").
    var displayName: String {
        rawValue.split(separator: " ").map(\.capitalized).joined(separator: " ")
    }

    /// Best-effort mapping from a free-text muscle name (e.g. from the AI blueprint) onto
    /// the catalog taxonomy. Handles common synonyms and plurals; nil if unrecognized.
    static func lenient(_ raw: String) -> Muscle? {
        let s = raw.lowercased().trimmingCharacters(in: .whitespaces)
        if let exact = Muscle(rawValue: s) { return exact }
        switch s {
        case "abs", "ab", "core", "abdominal": return .abdominals
        case "quads", "quad", "thighs", "legs": return .quadriceps
        case "hams", "ham", "hamstring": return .hamstrings
        case "calf": return .calves
        case "glute", "butt": return .glutes
        case "back", "upper back", "lat": return .lats
        case "mid back": return .middleBack
        case "low back", "lumbar": return .lowerBack
        case "delts", "delt", "shoulder", "deltoids": return .shoulders
        case "bi", "bicep": return .biceps
        case "tri", "tricep": return .triceps
        case "pecs", "pec", "pectorals": return .chest
        case "trap", "trapezius": return .traps
        case "forearm": return .forearms
        case "abductor": return .abductors
        case "adductor": return .adductors
        default: return nil
        }
    }
}

/// Equipment required for an exercise. `nil`/"None" upstream -> `.unknown` is avoided;
/// we model "no equipment recorded" as an optional on the model instead.
enum Equipment: String, Codable, CaseIterable, Identifiable, Sendable {
    case barbell, dumbbell, machine, cable
    case bodyOnly = "body only"
    case bands, kettlebells
    case ezCurlBar = "e-z curl bar"
    case exerciseBall = "exercise ball"
    case foamRoll = "foam roll"

//
//  AthleteContextTests.swift
//  ReplogTests
//
//  The athlete digest that grounds the AI planner in real logged training: per-lift
//  summaries, weekly volume, relevance ordering, windowing, and token-budgeted rendering.
//

import Testing
import Foundation
@testable import Replog

@MainActor
struct AthleteContextTests {

    private let catalog = ExerciseCatalog(bundle: .main)
    private let now = Date(timeIntervalSince1970: 1_750_000_000)

    /// A real catalog exercise with `muscle` as a PRIMARY mover, so exIds resolve and
    /// weekly volume attributes to the expected muscle.
    private func exercise(_ muscle: Muscle, offset: Int = 0) -> Exercise {
        catalog.exercises(forMuscle: muscle).filter { $0.primaryMuscles.contains(muscle) }[offset]
    }

    private func entry(_ exId: String, daysAgo: Int, topW: Double, topR: Int, sets: Int = 3) -> HistoryEntry {
        HistoryEntry(exId: exId,
                     date: now.addingTimeInterval(-Double(daysAgo) * 86_400),
                     topW: topW, topR: topR,
                     e1rm: Formulas.e1rmRounded(kg: topW, reps: topR),
                     sets: Array(repeating: RecordedSet(w: topW, r: topR), count: sets))
    }

    // MARK: - Building

    @Test func emptyHistoryYieldsEmptyContext() {
        let context = AthleteContext.make(history: [], catalog: catalog, now: now)
        #expect(context.isEmpty)
        #expect(context == .empty)
        #expect(context.promptSection(maxTokens: 500).isEmpty)
    }

